<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import { management, type Library } from '../api/management';
import AsyncState from '../components/AsyncState.vue';
const rows=ref<Library[]>([]),page=ref(1),total=ref(0),query=ref(''),loading=ref(true),error=ref('');
async function load(){loading.value=true;error.value='';try{const result=await management.libraries(page.value,query.value);rows.value=result.items;total.value=result.total;}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
async function name(library?:Library){try{const {value}=await ElMessageBox.prompt('题库名称',library?'重命名题库':'新建题库',{inputValue:library?.title||'',inputValidator:v=>!!v?.trim()&&v.length<=200||'请填写 1 至 200 字的名称',confirmButtonText:'保存',cancelButtonText:'取消'});if(library)await management.renameLibrary(library.id,value);else await management.createLibrary(value);await load();}catch(e){if(e instanceof Error)ElMessage.error(e.message);}}
onMounted(load);
</script>
<template><div class="page"><div class="page-heading"><h1>题库管理</h1><div class="action-group"><RouterLink to="/teacher/import"><el-button>批量导入</el-button></RouterLink><el-button type="primary" @click="name()">新建题库</el-button></div></div><div class="section-bar"><h2>题库 <span>{{total}}</span></h2><el-input v-model="query" clearable class="search-input" placeholder="搜索题库名称" @change="page=1;load()" @keyup.enter="page=1;load()"/></div><AsyncState :loading="loading" :error="error" :empty="!rows.length" empty-text="暂无题库，可新建题库或批量导入。" @retry="load"><div class="library-grid"><article v-for="library in rows" :key="library.id" class="panel library-card"><RouterLink :to="`/teacher/problems/${library.id}`"><span class="library-symbol" aria-hidden="true">▤</span><h2>{{library.title}}</h2><p>{{library.problemCount}} 道题目</p><span class="library-enter">管理题目 →</span></RouterLink><el-button link @click="name(library)">重命名</el-button></article></div></AsyncState><el-pagination v-if="total>100" class="mt" v-model:current-page="page" :total="total" :page-size="100" layout="prev,pager,next" @current-change="load"/></div></template>
<style scoped>.library-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:20px}.library-card{position:relative;padding:0;transition:border-color .2s,transform .2s}.library-card:hover{border-color:#9bc9c8;transform:translateY(-2px)}.library-card>a{display:block;padding:25px}.library-card h2{margin:16px 0 8px;overflow-wrap:anywhere}.library-card p{color:#7e909e;font-size:12px}.library-symbol{font-size:25px;color:#168d91}.library-enter{font-size:12px;color:#168d91}.library-card>.el-button{position:absolute;right:20px;bottom:22px}@media(prefers-reduced-motion:reduce){.library-card{transition:none;transform:none}}</style>
